  fr: (n) => `${n}\u00a0textes adoptés lors des récentes sessions plénières\u00a0:`,
  es: (n) => `${n} textos adoptados en recientes sesiones plenarias:`,
  nl: (n) => `${n} teksten aangenomen in recente plenaire vergaderingen:`,
