/**
 * Fetch MEPs feed from MCP, returning both items and the API's reported total count.
 * The `total` from the API response reflects all matching records in the feed,
 * which may exceed the `limit` parameter (currently capped at 100 per request).
 *
 * The limit is set to 100 (the EP API maximum) so the fetched sample is large
 * enough to populate a meaningful truncation note ("showing 10 of N") while
 * keeping each request bounded.  When the feed contains more than 100 MEP
 * updates, the `total` field in the API response carries the true count.
 *
 * @param client - MCP client or null
 * @param timeframe - How far back to look (default: 'one-week')
 * @returns Object with `items` array and `total` count from the API
 */
export async function fetchMEPsFeedWithTotal(
  client: EuropeanParliamentMCPClient | null,
  timeframe: FeedTimeframe = 'one-week'
): Promise<{ items: MEPFeedItem[]; total: number }> {
  if (!client) return { items: [], total: 0 };
  try {
    console.log(`${MCP_FETCH_PREFIX} Fetching MEPs feed (${timeframe})...`);
    const result = await callMCP(
      () => client.getMEPsFeed({ timeframe, limit: 100 }),
      undefined,
      'get_meps_feed'
    );
    const { items: rawItems, total } = parseFeedEnvelope(result);
    const items = rawItems.map((item) => ({
      id: String(item['id'] ?? item['mepId'] ?? ''),
      name: String(item['name'] ?? item['label'] ?? item['title'] ?? 'Unknown'),
      date: String(item['date'] ?? item['published'] ?? item['updated'] ?? ''),
      country: item['country'] ? String(item['country']) : undefined,
      group: item['group'] ? String(item['group']) : undefined,
      url: item['url'] ? String(item['url']) : undefined,
      identifier: item['identifier'] ? String(item['identifier']) : undefined,
      label: item['label'] ? String(item['label']) : undefined,
    }));
    return { items, total };
  } catch (error) {
    if (isStopRetryError(error)) return { items: [], total: 0 };
    const message = error instanceof Error ? error.message : String(error);
    console.warn(`${WARN_PREFIX} get_meps_feed failed:`, message);
    return { items: [], total: 0 };
  }
}

/**
 * Fetch a fixed-window EP API v2 feed that ignores the `timeframe` parameter.
 *
 * The EP MCP server splits feed tools into two groups — sliding-window feeds
 * accept `timeframe`/`startDate`, fixed-window feeds (documents,
 * plenary_documents, committee_documents, plenary_session_documents,
 * parliamentary_questions, corporate_bodies, controlled_vocabularies) serve a
 * server-defined window. As of v1.2.13 the server silently ignores
 * `timeframe`/`startDate` on fixed-window tools
 * (Hack23/European-Parliament-MCP-Server#379); pre-v1.2.13 it rejected them
 * with `INVALID_PARAMS` (#377). This helper issues a single RPC either way —
 * there is no point in timeframe-widening retry loops because the server does
 * not narrow/widen results based on timeframe.
 *
 * @param client - MCP client (null returns `[]`)
 * @param toolName - Tool name for log messages
 * @param callFn - Callback that issues the feed RPC
 * @returns Array of mapped feed items (may be empty)
 */
async function fetchFixedWindowFeed(
  client: EuropeanParliamentMCPClient | null,
  toolName: string,
  callFn: () => Promise<MCPToolResult | undefined>
): Promise<
  {
    id: string;
    title: string;
    date: string;
    type?: string | undefined;
    url?: string | undefined;
    identifier?: string | undefined;
    label?: string | undefined;
  }[]
> {
  if (!client) return [];
  try {
    console.log(`${MCP_FETCH_PREFIX} Fetching ${toolName}...`);
    const result = await callMCP(callFn, undefined, toolName);
    return parseFeedResult(result).map((item) => mapFeedItemBase(item));
  } catch (error) {
    if (isStopRetryError(error)) return [];
    const message = error instanceof Error ? error.message : String(error);
    console.warn(`${WARN_PREFIX} ${toolName} failed:`, message);
    return [];
  }
}

