  const langGrid = buildFooterLangGrid(lang, pathPrefix);

  return `<footer class="site-footer" role="contentinfo">
    <div class="footer-content">
      <div class="footer-section">
        <h3>${aboutHeading}</h3>
        <p>${aboutText}</p>${articlesLine}
