          <li><a href="${pathPrefix}${lang === 'en' ? 'index.html' : `index-${lang}.html`}">${homeLabel}</a></li>
          <li><a href="${pathPrefix}${lang === 'en' ? 'sitemap.html' : `sitemap_${lang}.html`}">${sitemapLabel}</a></li>
