import type {
  VotingAnomalyIntelligence,
  CoalitionIntelligence,
  MEPInfluenceScore,
  LegislativeVelocity,
  StakeholderPerspective,
  StakeholderOutcomeMatrix,
  AnalysisStakeholderType,
